#include <stdio.h>

static long long floor_div(long long a, long long b) {
    long long q = a / b;
    if (a % b != 0 && a < 0) {
        q--;
    }
    return q;
}

int main(void) {
    long long l, r, k;
    while (scanf("%lld %lld %lld", &l, &r, &k) == 3) {
        printf("%lld\n", floor_div(r, k) - floor_div(l - 1, k));
    }
    return 0;
}

