#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char a[3], b[3];
    while (scanf("%2s %2s", a, b) == 2) {
        int dx = abs(a[0] - b[0]);
        int dy = abs(a[1] - b[1]);
        int king = dx > dy ? dx : dy;
        int rook, bishop, queen;
        if (dx == 0 && dy == 0) {
            rook = bishop = queen = 0;
        } else {
            rook = (dx == 0 || dy == 0) ? 1 : 2;
            if ((dx + dy) % 2 != 0) {
                bishop = -1;
            } else {
                bishop = dx == dy ? 1 : 2;
            }
            queen = (rook == 1 || bishop == 1) ? 1 : 2;
        }
        printf("%d %d %d %d\n", king, rook, bishop, queen);
    }
    return 0;
}

